// Traegt hier jeweils die Zeilen ein, deren Bild-bezogener Fehlerzustand
// manuell zurueckgesetzt werden soll, damit P6 (Bildgenerierung) sie beim
// naechsten Lauf erneut aufgreift.
// 2026-07-28 (2. Verwendung): vol_10731 (2026/152-01) hatte imageStage=composed,
// aber die Datei unter .../02_reaktion/Instagram/final_vol_10731.png existiert
// nachweislich nicht mehr in Nextcloud (404 bei P8s Download-Versuch, seit
// 12:52 Uhr stuendlich). Upload-Fehlerpruefung in P6 ("Stelle Kontext nach
// Nextcloud Upload wieder her") ist korrekt, vermutlich einmaliger Nextcloud-
// Speicherfehler nach angeblich erfolgreichem Upload. Bild wird neu erzeugt.
const TARGETS = [
  { vorgangKey: 'vol_10731', vorgangsnummer: '2026/152-01' }
];

if (!TARGETS.length) {
  throw new Error('[ImageStage-Reset] TARGETS im Node "Konfiguriere Ziele" befuellen.');
}

return TARGETS.map(t => ({
  json: {
    vorgangKey: t.vorgangKey,
    vorgangsnummer: t.vorgangsnummer,
    imageStage: 'not_started',
    visualPromptStage: 'needs_prompt',
    visualDecisionReason: '',
    contentErrorReason: '',
    last_error_code: '',
    last_error_message: '',
    last_error_stage: '',
    last_error_at: '',
    next_retry_at: '',
    retry_count: 0
  }
}));
